let rawLog = msg.payload;
const connId = msg.connection.id;

msg.payload = rawLog.map(({
    id,
    content,
    createdAt,
    username,
    files,
    rayvnFileIds
}) => ({
    id,
    text: content,
    timeCreated: new Date(createdAt).getTime(),
    loggedByFullName: username,
    client: "wasos",
    target: "rayvn",
    connection_id: connId,
    files: files || [],
    rayvnFileIds: rayvnFileIds || []
}));

return msg;
